#!/usr/bin/env node
// tier: T2
/**
 * cam-awareness-inject.mjs — CAM-domain prism-awareness injector (slot:kilo-gated SessionStart)
 *
 * The CAM-scoped sibling of awareness-snapshot-inject.mjs. Reads
 * state/shared/CAM-AWARENESS-SNAPSHOT.md (generated by scripts/cam-awareness-snapshot.mjs)
 * and emits a compact ~12-line digest as SessionStart additionalContext so a kilo
 * session always boots with its OWN domain (CAM galaxy: engines, dispatcher surface,
 * triad, invariants, PSN edges, high-ROI memories) in view — the operator's
 * "custom one tailored to your domain so you always have context on your domain".
 *
 * GATE (zero-dependency, slot-worktree-native): injects ONLY when the session's cwd
 * is on branch `slot/kilo`. A delta chat is on `slot/delta`, golf/integrator on
 * `cad-fusion-live-ms0` → neither injects. Branch is read from .git/HEAD via fs
 * (worktree .git-file indirection handled) — NO child_process. Scopes correctly both
 * pre-merge (worktree) and post-merge (fleet-wide via settings.json).
 *
 * Read-only by design: it does NOT regenerate the snapshot (that is the generator's
 * job, run by kilo / a cadence). A stale snapshot is surfaced with an explicit regen
 * hint rather than silently trusted (R12). Fail-soft: any error → exit 0, never breaks
 * SessionStart.
 *
 * Disable:        PRISM_CAM_AWARENESS_INJECT=0
 * Bypass gate:    PRISM_CAM_AWARENESS_FORCE=1   (inject regardless of branch — testing)
 * Stale window:   PRISM_CAM_AWARENESS_STALE_HOURS=<n>  (default 48)
 */

import { readFileSync, statSync } from "node:fs";
import path from "node:path";

const ENABLED = process.env.PRISM_CAM_AWARENESS_INJECT !== "0";
const FORCE = process.env.PRISM_CAM_AWARENESS_FORCE === "1";
const STALE_HOURS = parseInt(process.env.PRISM_CAM_AWARENESS_STALE_HOURS, 10) || 48;
const TARGET_BRANCH = "slot/kilo";
const SNAPSHOT_REL = path.join("state", "shared", "CAM-AWARENESS-SNAPSHOT.md");
const REGEN_CMD = "node scripts/cam-awareness-snapshot.mjs";
const MS_PER_HOUR = 3_600_000;
const STDIN_TIMEOUT_MS = 500;
const HEADLINE_MAX = 3;
const INVARIANT_MAX = 2;

function readStdin(timeoutMs = STDIN_TIMEOUT_MS) {
  return new Promise((resolve) => {
    let data = "";
    let done = false;
    const finish = () => { if (!done) { done = true; resolve(data); } };
    try {
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (c) => { data += c; });
      process.stdin.on("end", finish);
      process.stdin.on("error", finish);
      setTimeout(finish, timeoutMs);
    } catch { finish(); }
  });
}

/** Resolve the git directory for `root`, handling the worktree `.git`-file case. */
function resolveGitDir(root) {
  const dotGit = path.join(root, ".git");
  try {
    const st = statSync(dotGit);
    if (st.isDirectory()) return dotGit;
    if (st.isFile()) {
      const m = readFileSync(dotGit, "utf8").trim().match(/^gitdir:\s*(.+)$/m);
      if (m) return path.resolve(root, m[1].trim());
    }
  } catch { /* fall through */ }
  return null;
}

function branchOf(root) {
  const gitDir = resolveGitDir(root);
  if (!gitDir) return null;
  try {
    const head = readFileSync(path.join(gitDir, "HEAD"), "utf8").trim();
    const m = head.match(/^ref:\s*refs\/heads\/(.+)$/);
    return m ? m[1].trim() : null; // detached HEAD → not a slot branch → no inject
  } catch { return null; }
}

/** Pull a `## <heading>` section's lines (until the next `## `). */
function section(lines, heading) {
  const i = lines.findIndex((l) => l.trim().startsWith(`## ${heading}`));
  if (i < 0) return [];
  const out = [];
  for (let j = i + 1; j < lines.length; j++) {
    if (lines[j].trim().startsWith("## ")) break;
    out.push(lines[j]);
  }
  return out;
}

function compact(md, staleHours) {
  const lines = md.split(/\r?\n/);
  const headline = section(lines, "Headline").filter((l) => l.trim().startsWith("-"));
  const triad = section(lines, "Triad + key dispatcher families").filter((l) => l.trim().startsWith("-"));
  const invariants = section(lines, "Invariants").filter((l) => /^\d+\./.test(l.trim()));

  const out = [];
  out.push("## 🛠️ CAM Awareness (slot:kilo domain — auto-injected; full: state/shared/CAM-AWARENESS-SNAPSHOT.md)");
  out.push("");
  if (headline.length) {
    out.push("**CAM galaxy now:**");
    headline.slice(0, HEADLINE_MAX).forEach((l) => out.push(l));
    out.push("");
  }
  if (triad.length) {
    triad.slice(0, 1).forEach((l) => out.push(l));
  }
  if (invariants.length) {
    out.push("**Top invariants:** " + invariants.slice(0, INVARIANT_MAX).map((l) => l.trim()).join("  "));
  }
  out.push("");
  out.push("_Pipeline: CAD(delta)→**CAM(kilo)**→post(echo). Galaxy: `mcp-server/src/engines/cam/`. PSN edges + memories in the full snapshot._");
  if (staleHours != null && staleHours > STALE_HOURS) {
    out.push(`_⚠ snapshot ${staleHours}h old (>${STALE_HOURS}h) — regen: \`${REGEN_CMD}\`._`);
  }
  return out.join("\n");
}

function emit(ctx) {
  process.stdout.write(JSON.stringify({
    hookSpecificOutput: { hookEventName: "SessionStart", additionalContext: ctx },
  }));
}

async function main() {
  if (!ENABLED) return;
  const raw = await readStdin();
  let cwd = process.cwd();
  try {
    const j = JSON.parse(raw || "{}");
    if (typeof j.cwd === "string" && j.cwd.length > 0) cwd = j.cwd;
  } catch { /* fall back to process.cwd() */ }

  if (!FORCE) {
    const br = branchOf(cwd);
    if (br !== TARGET_BRANCH) return; // not a kilo session → silent no-op
  }

  const snapPath = path.join(cwd, SNAPSHOT_REL);
  let md;
  try { md = readFileSync(snapPath, "utf8"); } catch { return; } // no snapshot → nothing to inject
  let staleHours = null;
  try { staleHours = Math.round((Date.now() - statSync(snapPath).mtimeMs) / MS_PER_HOUR); } catch { /* ignore */ }

  const block = compact(md, staleHours);
  if (block) emit(block);
}

main()
  .catch((err) => { process.stderr.write(`[cam-awareness-inject] ${err?.message || err}\n`); })
  .finally(() => process.exit(0));
